mapper.select:
select AMOUNT amount,QTY qty from CHB_INVESTHOLD_INFO_SUB
where REGIST_BANK_CODE = #{dto.registBankCode,jdbcType=VARCHAR}
and PRD_REGIST_CODE = #{dto.prdRegistCode,jdbcType=VARCHAR}
and INDENTIFY_MARK = #{dto.indentifyMark,jdbcType=VARCHAR}
and CCY = #{dto.ccy,jdbcType=VARCHAR}
and HOLD_DATE = #{dto.holdDate,jdbcType=DATE}

    and SEND_STATUS in('02','03')
